package com.hbm.satellite.cargo.client;
import com.hbm.client.model.*;import com.hbm.satellite.cargo.SatellitePod;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.entity.*;import net.minecraft.resources.ResourceLocation;
/** Actual original smooth dropship.obj Pod plus4Leg parts, exact45+90i and150(1-legs) pivots. */
public final class SatellitePodRenderer extends EntityRenderer<SatellitePod>{
 private static final ResourceLocation MODEL=ResourceLocation.parse("hbm:models/dropship.obj"),TEXTURE=ResourceLocation.parse("hbm:textures/entity/dropship.png");public SatellitePodRenderer(EntityRendererProvider.Context context){super(context);}@Override public ResourceLocation getTextureLocation(SatellitePod pod){return TEXTURE;}@Override public void render(SatellitePod pod,float yaw,float partial,PoseStack poses,MultiBufferSource buffers,int light){var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);var vertex=buffers.getBuffer(RenderType.entityCutout(TEXTURE));LegacyObjRenderer.renderOnly(mesh,poses,vertex,light,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY,-1,LegacyObjRenderer.Convention.HFR,"Pod");float legs=pod.prevLegs+(pod.legs-pod.prevLegs)*partial;for(int i=0;i<4;i++){poses.pushPose();poses.mulPose(Axis.YP.rotationDegrees(45+90*i));poses.translate(.5,1.75,0);poses.mulPose(Axis.ZP.rotationDegrees(150*(1F-legs)));poses.translate(-.5,-1.75,0);LegacyObjRenderer.renderOnly(mesh,poses,vertex,light,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY,-1,LegacyObjRenderer.Convention.HFR,"Leg");poses.popPose();}}@Override public boolean shouldRender(SatellitePod pod,net.minecraft.client.renderer.culling.Frustum frustum,double x,double y,double z){return super.shouldRender(pod,frustum,x,y,z);}
}
